from itertools import combinations
from typing import Dict, List, Set

def octahedron() -> Dict[int, Set[int]]:
    verts = list(range(6))
    adj = {v: set() for v in verts}
    for u, v in combinations(verts, 2):
        if u // 2 != v // 2:
            adj[u].add(v); adj[v].add(u)
    return adj

def is_clique(g, s):
    return all(v in g[u] for u, v in combinations(sorted(s), 2))

def maximal_cliques(g):
    verts = sorted(g); found = []
    for r in range(1, len(verts) + 1):
        for c in combinations(verts, r):
            s = set(c)
            if is_clique(g, s): found.append(s)
    return [frozenset(s) for s in found if not any(s < t for t in found)]

if __name__ == "__main__":
    g = octahedron()
    cols = sorted((tuple(sorted(c)) for c in maximal_cliques(g)))
    print("maximal cliques:", cols)
    for v in range(6):
        print("v%d:" % v, " ".join("1" if v in c else "." for c in cols))

