        if u//2!=v//2: g[u].add(v); g[v].add(u)
    return g

def is_clique(g,s):
    return all(v in g[u] for u,v in combinations(sorted(s),2))

def max_cliques(g):
    found=[]
    for r in range(1,7):
        for c in combinations(range(6),r):
            s=set(c)
            if is_clique(g,s): found.append(s)
